import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CU_ytobU.js";var i=JSON.parse(`{"title":"Class: TickList","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: TickList"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/engine-systems/classes/TickList"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/engine-systems/classes/TickList"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/engine-systems/src"}},"headers":[],"relativePath":"api/@jsprismarine/engine-systems/classes/TickList.md","filePath":"api/@jsprismarine/engine-systems/classes/TickList.md","lastUpdated":1793966870000}`),a={name:`api/@jsprismarine/engine-systems/classes/TickList.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/engine-systems</a> / TickList</p><h1 id="class-ticklist" tabindex="-1">Class: TickList <a class="header-anchor" href="#class-ticklist" aria-label="Permalink to “Class: TickList”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L88" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:88</a></p><p>One tick list: Java&#39;s <code>LevelTicks</code> for a single kind, block or fluid.</p><p>Java shards the queue per chunk and merges the shards in <code>drainContainers</code>. This keeps one queue for the whole world, which produces the same order whenever every due tick has the same trigger tick. The two differ only for a backlog that the per-tick budget left behind, and there this ordering is the stricter one: it runs the oldest ticks first.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new TickList</strong>(): <code>TickList</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>TickList</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="clearat" tabindex="-1">clearAt() <a class="header-anchor" href="#clearat" aria-label="Permalink to “clearAt()”">​</a></h3><blockquote><p><strong>clearAt</strong>(<code>at</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L147" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:147</a></p><p>Remove every queued tick at one position, which a destroyed block needs.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><p><a href="./../#blockposition"><code>BlockPosition</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="count" tabindex="-1">count() <a class="header-anchor" href="#count" aria-label="Permalink to “count()”">​</a></h3><blockquote><p><strong>count</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L132" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:132</a></p><p>How many ticks are queued.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="hasscheduledtick" tabindex="-1">hasScheduledTick() <a class="header-anchor" href="#hasscheduledtick" aria-label="Permalink to “hasScheduledTick()”">​</a></h3><blockquote><p><strong>hasScheduledTick</strong>(<code>at</code>, <code>type</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L118" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:118</a></p><p>Whether a tick is queued for this position and type.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at-1" tabindex="-1">at <a class="header-anchor" href="#at-1" aria-label="Permalink to “at”">​</a></h5><p><a href="./../#blockposition"><code>BlockPosition</code></a></p><h5 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to “type”">​</a></h5><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="schedule" tabindex="-1">schedule() <a class="header-anchor" href="#schedule" aria-label="Permalink to “schedule()”">​</a></h3><blockquote><p><strong>schedule</strong>(<code>at</code>, <code>type</code>, <code>triggerTick</code>, <code>priority?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L109" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:109</a></p><p>Queue a tick, unless one is already queued for the same position and type.</p><p>Java&#39;s <code>LevelChunkTicks.schedule</code> adds to a <code>ticksPerPosition</code> set first and drops the tick when the set already holds it, which is the rule the wiki states for repeaters: &quot;any attempt to schedule a tick while one already exists is completely ignored&quot;.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at-2" tabindex="-1">at <a class="header-anchor" href="#at-2" aria-label="Permalink to “at”">​</a></h5><p><a href="./../#blockposition"><code>BlockPosition</code></a></p><p>The position the tick fires for.</p><h5 id="type-1" tabindex="-1">type <a class="header-anchor" href="#type-1" aria-label="Permalink to “type”">​</a></h5><p><code>string</code></p><p>The block or fluid identifier.</p><h5 id="triggertick" tabindex="-1">triggerTick <a class="header-anchor" href="#triggertick" aria-label="Permalink to “triggerTick”">​</a></h5><p><code>number</code></p><p>The absolute game tick to fire on.</p><h5 id="priority" tabindex="-1">priority? <a class="header-anchor" href="#priority" aria-label="Permalink to “priority?”">​</a></h5><p><code>number</code> = <code>TICK_PRIORITIES.NORMAL</code></p><p>One of <a href="./../#tick-priorities">TICK_PRIORITIES</a>, defaulting to <code>NORMAL</code>.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>True when the tick was queued, false when one already existed.</p><hr><h3 id="snapshot" tabindex="-1">snapshot() <a class="header-anchor" href="#snapshot" aria-label="Permalink to “snapshot()”">​</a></h3><blockquote><p><strong>snapshot</strong>(): readonly <a href="./../#scheduledtick"><code>ScheduledTick</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L142" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:142</a></p><p>Copies the pending ticks in drain order for diagnostics and replay comparisons.</p><p>This sorts a copy, leaving the live queue order untouched. Each position is copied too, so callers cannot mutate a queued tick through the returned state.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#scheduledtick"><code>ScheduledTick</code></a>[]</p><hr><h3 id="tick" tabindex="-1">tick() <a class="header-anchor" href="#tick" aria-label="Permalink to “tick()”">​</a></h3><blockquote><p><strong>tick</strong>(<code>currentTick</code>, <code>run</code>, <code>maxTicks?</code>, <code>deadline?</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L174" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:174</a></p><p>Collect every tick due at <code>currentTick</code>, up to the budget, and run them.</p><p>Collection takes the oldest ticks first, as Java&#39;s per-chunk queues do. The collected batch then runs in <code>INTRA_TICK_DRAIN_ORDER</code>, priority before schedule order. A tick scheduled by a handler during the batch lands in a later game tick, never in the batch being run, which is what makes a repeater chain take its delay rather than collapsing into one tick.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="currenttick" tabindex="-1">currentTick <a class="header-anchor" href="#currenttick" aria-label="Permalink to “currentTick”">​</a></h5><p><code>number</code></p><p>The game tick to run.</p><h5 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to “run”">​</a></h5><p><a href="./../#tickhandler"><code>TickHandler</code></a></p><p>Called once per due tick, in order.</p><h5 id="maxticks" tabindex="-1">maxTicks? <a class="header-anchor" href="#maxticks" aria-label="Permalink to “maxTicks?”">​</a></h5><p><code>number</code> = <code>MAX_SCHEDULED_TICKS_PER_TICK</code></p><p>The per-tick budget, defaulting to Java&#39;s 65536.</p><h5 id="deadline" tabindex="-1">deadline? <a class="header-anchor" href="#deadline" aria-label="Permalink to “deadline?”">​</a></h5><p><code>number</code> = <code>Number.POSITIVE_INFINITY</code></p><p>A <code>performance.now()</code> time after which no further tick starts. The ticks it leaves stay queued, still due, and run first on the next game tick. A count is no bound on time: a slow host, or ticks that each scan a neighborhood, spend seconds inside 65536.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>How many ticks ran.</p><hr><h3 id="willtickthistick" tabindex="-1">willTickThisTick() <a class="header-anchor" href="#willtickthistick" aria-label="Permalink to “willTickThisTick()”">​</a></h3><blockquote><p><strong>willTickThisTick</strong>(<code>at</code>, <code>type</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e3051f88e17c5daef5b00d6aa43d8c297193b0e6/packages/engine-systems/src/scheduler.ts#L127" target="_blank" rel="noreferrer">engine-systems/src/scheduler.ts:127</a></p><p>Whether a queued tick is in the batch the current game tick is running, which is Java&#39;s <code>LevelTicks.willTickThisTick</code>. A diode calls it to avoid rescheduling a tick that is about to run.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at-3" tabindex="-1">at <a class="header-anchor" href="#at-3" aria-label="Permalink to “at”">​</a></h5><p><a href="./../#blockposition"><code>BlockPosition</code></a></p><h5 id="type-2" tabindex="-1">type <a class="header-anchor" href="#type-2" aria-label="Permalink to “type”">​</a></h5><p><code>string</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p>`,103)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};